## Summary plot (domain-by-rating)


::: {#cell-fig-rob-bars .cell}

```{.r .cell-code .hidden}
#| label: fig-rob-bars
#| fig-cap: "Distribution of QUIPS judgments across studies, per domain."
rob_long |>
  count(domain, score_lbl) |>
  group_by(domain) |>
  mutate(pct = n / sum(n)) |>
  ggplot(aes(y = domain, x = pct, fill = score_lbl)) +
  geom_col(width = 0.7) +
  geom_text(aes(label = scales::percent(pct, accuracy = 1)),
            position = position_stack(vjust = 0.5),
            color = "white", size = 3, fontface = "bold") +
  scale_x_continuous(labels = scales::percent_format(accuracy = 1)) +
  scale_fill_manual(values = c("Low" = "#C9D6E2", "Moderate" = "#7F9DB9",
                                "High" = "#3F5A75", "NR" = "#E3E9EF"),
                    name = "Risk of bias") +
  labs(x = NULL, y = NULL) +
  theme_jama()
